<template>
  <section class="device-admin">
    <header class="module-header"><div><span class="admin-eyebrow">SEGURANÇA DAS CONTAS</span><h2>Dispositivos e alertas</h2><p>Uma instalação de navegador é um registro. Abas da mesma instalação contam uma vez.</p></div><button class="admin-button" @click="devices.refresh()" :disabled="devices.loading"><i aria-hidden="true" class="mdi mdi-refresh"/> Atualizar</button></header>
    <p class="admin-info">Conectados recentemente = atividade nos últimos 7 minutos. Sem atividade, o registro sai da contagem. O navegador pode suspender a atualização com a tela bloqueada. Os alertas são registrados enquanto a administração está aberta.</p>
    <p v-if="devices.error" class="admin-error" role="alert">{{ devices.error }}</p><p v-if="actionError" class="admin-error" role="alert">{{ actionError }}</p>
    <div class="admin-metrics"><article><span>Instalações recentes</span><strong>{{ devices.verified?devices.connected:'—' }}</strong></article><article><span>Contas com atividade</span><strong>{{ devices.verified?devices.groups.length:'—' }}</strong></article><article class="warning-metric"><span>Contas acima de 4</span><strong>{{ devices.verified?devices.excess.length:'—' }}</strong></article></div>
    <div class="admin-toolbar"><label>Mostrar<select v-model="onlyAlerts"><option :value="false">Todas as contas recentes</option><option :value="true">Somente acima de 4</option></select></label><label>Buscar conta recente<input v-model="search" placeholder="Nome, email ou UID"/></label><label>Abrir histórico por UID<input v-model="lookup" placeholder="Cole o UID da conta" @keyup.enter="inspect(lookup)"/></label><button class="admin-button" @click="inspect(lookup)" :disabled="!lookup.trim()">Abrir histórico</button></div>
    <p v-if="devices.loading" role="status">Carregando somente dispositivos com atividade recente…</p>
    <div v-else class="device-accounts"><article v-for="group in visibleGroups" :key="group.uid" class="device-account" :class="{risk:group.alert}"><div><h3>{{ accountName(group.uid) }}</h3><p>{{ devices.profiles[group.uid]?.email || group.uid }}</p><span v-if="group.alert" class="device-risk"><i aria-hidden="true" class="mdi mdi-alert-outline"/> Possível compartilhamento de conta</span></div><span class="device-count">{{ group.count }} <small>recentes</small></span><button class="admin-button" @click="inspect(group.uid)">Ver aparelhos</button></article><p v-if="!filteredGroups.length && devices.verified">{{ onlyAlerts?'Nenhuma conta acima de quatro instalações recentes.':'Nenhuma conta com atividade recente nesta busca.' }}</p></div>
    <button v-if="filteredGroups.length>visibleCount" class="admin-button" @click="visibleCount+=25">Mostrar mais contas recentes</button>
    <section class="device-alert-history"><h3>Últimos alertas registrados</h3><p class="admin-info">Revisar marca o alerta como visto. A conta continua funcionando. Ao cair para quatro ou menos, o painel encerra o alerta durante o monitoramento.</p><article v-for="alert in devices.alerts" :key="alert.id" :data-alert-uid="alert.uid" class="device-alert"><div><strong>{{ accountName(alert.uid) }}</strong><p>{{ alert.count }} instalações · {{ alert.active?'Acima do limite observado':'Encerrado' }} · {{ formatDate(alert.createdAt) }}</p><small v-if="alert.acknowledgedAt">Revisado em {{ formatDate(alert.acknowledgedAt) }}</small></div><button class="admin-button" @click="inspect(alert.uid)">Abrir conta</button><button class="admin-button" v-if="!alert.acknowledgedAt" @click="acknowledge(alert.uid)">Marcar revisado</button></article><p v-if="!devices.alerts.length">Nenhum alerta registrado.</p></section>
    <v-dialog v-model="historyOpen" max-width="860" :z-index="15000" aria-labelledby="device-history-title">
      <section class="device-history-dialog"><header class="module-header"><div><span class="admin-eyebrow">HISTÓRICO DA CONTA</span><h2 id="device-history-title">{{ accountName(selectedUid) }}</h2><p>{{ selectedUid }}</p></div><button class="admin-button" @click="historyOpen=false" aria-label="Fechar histórico de aparelhos"><i aria-hidden="true" class="mdi mdi-close"/></button></header>
        <p class="admin-info">{{ devices.countFor(selectedUid) }} instalações com atividade recente. Navegadores diferentes ou dados apagados criam registros diferentes; isso não prova quantas pessoas usam a conta.</p>
        <p v-if="historyError" class="admin-error" role="alert">{{ historyError }}</p><p v-if="historyLoading" role="status">Abrindo histórico…</p>
        <article v-for="device in history" :key="device.deviceId" class="history-device"><span class="history-icon"><i aria-hidden="true" class="mdi" :class="device.kind==='Computador'?'mdi-laptop':device.kind==='Tablet'?'mdi-tablet':'mdi-cellphone'"/></span><div><h3>{{ device.kind }} · {{ device.os }}</h3><p>{{ device.browser }}{{ device.installed?' · App instalado':'' }}</p><dl><div><dt>Primeiro registro</dt><dd>{{ formatDate(device.createdAt) }}</dd></div><div><dt>Último acesso registrado</dt><dd>{{ formatDate(device.lastLoginAt) }}</dd></div><div><dt>Última atividade</dt><dd>{{ formatDate(device.lastSeen) }}</dd></div></dl><code>{{ device.deviceId }}</code></div><span class="history-state" :class="{recent:deviceRecent(device,clock)}">{{ device.loggedOut?'Saiu da conta':deviceRecent(device,clock)?'Atividade recente':'Sem atividade recente' }}</span></article>
        <p v-if="!historyLoading&&!history.length">Ainda não há registros de aparelhos desta conta nesta versão.</p><button v-if="historyMore" class="admin-button" @click="loadHistory(false)" :disabled="historyLoading">Carregar registros anteriores</button>
      </section>
    </v-dialog>
  </section>
</template>
<script setup>
import { ref, computed, watch, onBeforeUnmount } from 'vue'
import { collection, getDocs, query, orderBy, limit, startAfter } from 'firebase/firestore'
import { db } from '@/firebase'
import { useDeviceAdminStore } from '@/stores/useDeviceAdminStore'
import { deviceRecent } from '@/utils/device-policy.mjs'
import { dateMillis } from '@/utils/access-policy.mjs'
const props=defineProps({accountUid:{type:String,default:''},inspectRequest:{type:Number,default:0}})
const devices=useDeviceAdminStore(),onlyAlerts=ref(false),search=ref(''),visibleCount=ref(25),lookup=ref(''),selectedUid=ref(''),historyOpen=ref(false),history=ref([]),historyMore=ref(false),historyLoading=ref(false),historyError=ref(''),actionError=ref(''),clock=ref(Date.now())
let cursor,generation=0
const timer=setInterval(()=>clock.value=Date.now(),15000)
const filteredGroups=computed(()=>devices.groups.filter(g=>(!onlyAlerts.value||g.alert)&&(`${accountName(g.uid)} ${devices.profiles[g.uid]?.email||''} ${g.uid}`.toLowerCase().includes(search.value.toLowerCase()))))
const visibleGroups=computed(()=>filteredGroups.value.slice(0,visibleCount.value))
watch(visibleGroups,groups=>devices.ensureProfiles(groups.map(g=>g.uid)),{immediate:true})
watch([()=>props.accountUid,()=>props.inspectRequest],([uid])=>{if(uid)inspect(uid)},{immediate:true})
watch([search,onlyAlerts],()=>visibleCount.value=25)
function accountName(uid){const p=devices.profiles[uid];return p?`${p.firstName||''} ${p.lastName||''}`.trim()||p.name||p.email||uid:uid}
function formatDate(value){const time=dateMillis(value);return time?new Date(time).toLocaleString('pt-BR'):'—'}
async function inspect(uid){uid=uid?.trim();if(!uid||uid.includes('/'))return;selectedUid.value=uid;lookup.value=uid;historyOpen.value=true;history.value=[];cursor=null;devices.ensureProfiles([uid]);await loadHistory(true)}
async function loadHistory(reset){const run=++generation,uid=selectedUid.value;historyLoading.value=true;historyError.value='';try{const terms=[orderBy('lastSeen','desc')];if(!reset&&cursor)terms.push(startAfter(cursor));const snap=await getDocs(query(collection(db,'users',uid,'devices'),...terms,limit(21)));if(run!==generation||uid!==selectedUid.value)return;const rows=snap.docs.slice(0,20);history.value=reset?rows.map(d=>d.data()):[...history.value,...rows.map(d=>d.data())];cursor=rows.at(-1);historyMore.value=snap.size>20}catch(e){if(run===generation)historyError.value=e.message}finally{if(run===generation)historyLoading.value=false}}
async function acknowledge(uid){actionError.value='';try{await devices.acknowledge(uid)}catch{actionError.value='Não foi possível marcar o alerta. Tente novamente.'}}
watch(historyOpen,open=>{if(!open)generation++})
onBeforeUnmount(()=>{clearInterval(timer);generation++})
</script>
<style scoped>
.device-accounts{display:grid;gap:10px}.device-account{display:flex;align-items:center;gap:18px;padding:18px;background:#16261e;border:1px solid #345743;border-radius:16px}.device-account.risk{background:#32271c;border-color:#9a703d}.device-account>div{flex:1;min-width:0}.device-account h3{font-size:16px;overflow-wrap:anywhere}.device-account p{font-size:12px;color:#b0c2b6;overflow-wrap:anywhere;margin-top:6px}.device-risk{display:flex;gap:6px;font-size:11px;color:#ffcf86;margin-top:10px}.device-count{text-align:center;font-size:28px;font-weight:700;min-width:60px}.device-count small{display:block;font-size:10px;font-weight:400;color:#abc1b3}.device-alert-history{margin-top:30px}.device-alert-history>h3{font-size:21px}.device-alert{display:flex;gap:10px;align-items:center;padding:16px 0;border-bottom:1px solid #2e4638}.device-alert>div{flex:1;min-width:0}.device-alert strong{font-size:14px;overflow-wrap:anywhere}.device-alert p,.device-alert small{font-size:11px;color:#b4c3b9;margin-top:6px}.device-history-dialog{padding:25px;background:#132219;color:#edf8f1;border:1px solid #40664c;border-radius:20px;max-height:85dvh;overflow:auto}.history-device{display:flex;gap:14px;padding:18px 0;border-bottom:1px solid #35513e}.history-icon{display:grid;place-items:center;flex:0 0 44px;height:44px;border-radius:12px;background:#233e2c;color:#ace8c3;font-size:25px}.history-device>div{flex:1;min-width:0}.history-device h3{font-size:15px}.history-device p{font-size:12px;color:#a8c4b2;margin-top:4px}.history-device dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:12px 0}.history-device dt{font-size:10px;color:#92b2a0}.history-device dd{font-size:11px;margin-top:4px}.history-device code{font-size:9px;color:#799f88;overflow-wrap:anywhere}.history-state{font-size:10px;color:#b0bdb4;align-self:flex-start;padding:6px;border:1px solid #47624f;border-radius:6px;white-space:nowrap}.history-state.recent{color:#aaf0c3;background:#234634;border-color:#4a855e}@media(max-width:700px){.device-account{flex-wrap:wrap;gap:10px;padding:15px}.device-account>div{flex-basis:calc(100% - 80px)}.device-account>.admin-button{width:100%}.device-alert{flex-wrap:wrap}.device-alert>div{flex-basis:100%}.device-history-dialog{padding:18px}.history-device{flex-wrap:wrap;gap:10px}.history-device>div{flex:1 1 calc(100% - 60px)}.history-device dl{grid-template-columns:1fr;gap:8px}.history-state{margin-left:54px;flex-basis:auto}.device-history-dialog .module-header{align-items:flex-start}.device-history-dialog .module-header>div{flex:1;min-width:0}.device-history-dialog .module-header button{flex:0 0 44px;width:44px;height:44px;padding:8px}.history-device h3{font-size:14px}}
</style>
